From a754fa3c6d410945545817fbe3cd4534f069e1f2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:33:56 +0100
Subject: [PATCH] plugins/slidingnotifications: don't animate notifications
 while locked

Animations only advance when the window is painted, so a notification
that closed under the lock screen stayed on its last frame and slid out
after unlocking. Skip them while locked and drop running ones on lock.

BUG: 497597
---
 .../slidingnotifications/slidingnotifications.cpp        | 9 ++++++---
 1 file changed, 6 insertions(+), 3 deletions(-)

diff --git a/src/plugins/slidingnotifications/slidingnotifications.cpp b/src/plugins/slidingnotifications/slidingnotifications.cpp
index 2713bde63d..c586e352d3 100644
--- a/src/plugins/slidingnotifications/slidingnotifications.cpp
+++ b/src/plugins/slidingnotifications/slidingnotifications.cpp
@@ -432,6 +432,9 @@ SlidingNotificationsEffect::SlidingNotificationsEffect()
 {
     connect(effects, &EffectsHandler::windowAdded, this, &SlidingNotificationsEffect::onWindowAdded);
     connect(effects, &EffectsHandler::windowClosed, this, &SlidingNotificationsEffect::onWindowClosed);
+    connect(effects, &EffectsHandler::screenLockingChanged, this, [this]() {
+        m_animations.clear();
+    });
 }

 bool SlidingNotificationsEffect::isActive() const
@@ -514,7 +517,7 @@ void SlidingNotificationsEffect::onWindowAdded(EffectWindow *window)
         return;
     }

-    if (effects->hasActiveFullScreenEffect()) {
+    if (effects->hasActiveFullScreenEffect() || effects->isScreenLocked()) {
         return;
     }

@@ -539,7 +542,7 @@ void SlidingNotificationsEffect::onWindowClosed(EffectWindow *window)
         return;
     }

-    if (effects->hasActiveFullScreenEffect()) {
+    if (effects->hasActiveFullScreenEffect() || effects->isScreenLocked()) {
         return;
     }

@@ -562,7 +565,7 @@ void SlidingNotificationsEffect::onWindowClosed(EffectWindow *window)

 void SlidingNotificationsEffect::onWindowFrameGeometryChanged(EffectWindow *window, const RectF &oldGeometry)
 {
-    if (effects->hasActiveFullScreenEffect()) {
+    if (effects->hasActiveFullScreenEffect() || effects->isScreenLocked()) {
         return;
     }

